import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Aturan Penyeberangan Bidang","description":"","frontmatter":{},"headers":[],"relativePath":"id/81-位面穿梭规则.md","filePath":"id/81-位面穿梭规则.md"}'),r={name:"id/81-位面穿梭规则.md"};function d(g,a,s,u,k,l){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="aturan-penyeberangan-bidang" tabindex="-1">Aturan Penyeberangan Bidang <a class="header-anchor" href="#aturan-penyeberangan-bidang" aria-label="Permalink to &quot;Aturan Penyeberangan Bidang&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>81</td></tr><tr><td>Modul</td><td>Interaksi Antar Bidang dan Aturan Waktu</td></tr><tr><td>Kata Kunci Inti</td><td>Penyeberangan bidang, izin penyeberangan, ambang energi, kalibrasi neo, pencegahan polusi</td></tr></tbody></table><h2 id="_1-posisi-hukum-tindakan-penyeberangan" tabindex="-1">1. Posisi Hukum Tindakan Penyeberangan <a class="header-anchor" href="#_1-posisi-hukum-tindakan-penyeberangan" aria-label="Permalink to &quot;1. Posisi Hukum Tindakan Penyeberangan&quot;">​</a></h2><p>Penyeberangan bidang merujuk pada tindakan individu atau kelompok makhluk hidup, melalui sarana teknologi atau kemampuan kultivasi, menyeberangi hambatan hukum dari satu bidang untuk masuk ke bidang lain. Dalam kerangka hukum peradaban simbiosis neo, penyeberangan bidang tergolong sebagai &quot;tindakan khusus berisiko tinggi&quot; dan harus tunduk pada manajemen izin yang ketat serta pengawasan proses. Pasal 47 &quot;Konstitusi Simbiosis&quot; secara eksplisit menetapkan: &quot;Tidak ada organisasi atau individu yang dapat melakukan penyeberangan antar bidang tanpa izin, maupun menggunakan penyeberangan bidang untuk melakukan kegiatan penjarahan, intervensi, atau polusi terhadap peradaban bidang lain.&quot;</p><p>Alasan mendasar mengapa penyeberangan bidang memerlukan pengendalian ketat adalah bahwa tindakan penyeberangan itu sendiri dapat menimbulkan dampak ganda pada bidang target: gangguan hukum, injeksi energi, polusi kesadaran, invasi mikroba, dan intervensi budaya, antara lain. Dampak ini, dalam tingkat ringan, menyebabkan anomali lokal pada bidang target; dalam tingkat berat, dapat mengubah lintasan evolusi peradabannya, bahkan menyebabkan keruntuhan hukum. Oleh karena itu, tujuan inti aturan penyeberangan adalah &quot;mengendalikan dampak eksternal tindakan penyeberangan dalam batas yang dapat diterima&quot;.</p><h2 id="_2-sistem-klasifikasi-izin-penyeberangan" tabindex="-1">2. Sistem Klasifikasi Izin Penyeberangan <a class="header-anchor" href="#_2-sistem-klasifikasi-izin-penyeberangan" aria-label="Permalink to &quot;2. Sistem Klasifikasi Izin Penyeberangan&quot;">​</a></h2><p>Hengyuanzhou menerapkan sistem klasifikasi izin penyeberangan bidang, membagi izin menjadi empat tingkat sesuai dengan tujuan penyeberangan, jenis bidang target, dan kualifikasi penyeberang:</p><table tabindex="0"><thead><tr><th>Tingkat Izin</th><th>Skenario yang Berlaku</th><th>Lembaga Pemberi Izin</th><th>Masa Berlaku</th><th>Kondisi Tambahan</th></tr></thead><tbody><tr><td>Tingkat A (Pengamatan Arkeologi)</td><td>Arkeologi murni pengamatan, tanpa kontak fisik apa pun</td><td>Biro Administrasi Bidang</td><td>Tugas tunggal</td><td>Harus menggunakan skema cermin salinan + ruang terisolasi</td></tr><tr><td>Tingkat B (Pertukaran Akademik)</td><td>Pertukaran pengetahuan terbatas dengan peradaban bidang target</td><td>Biro Administrasi Bidang + Kementerian Kebudayaan</td><td>Maksimal satu tahun</td><td>Harus menandatangani perjanjian tidak saling intervensi</td></tr><tr><td>Tingkat C (Kerja Sama Sumber Daya)</td><td>Kerja sama sumber daya dan teknologi di bawah premis kesetaraan dan saling menguntungkan</td><td>Persetujuan khusus Dewan Neo</td><td>Maksimal tiga tahun</td><td>Harus mendapatkan persetujuan peradaban bidang target</td></tr><tr><td>Tingkat D (Intervensi Darurat)</td><td>Intervensi kemanusiaan ketika bidang target menghadapi krisis tingkat kepunahan</td><td>Resolusi darurat Dewan Neo</td><td>Selama krisis berlangsung</td><td>Harus menyerahkan laporan intervensi lengkap setelahnya</td></tr></tbody></table><p>Izin penyeberangan tingkat apa pun melarang tindakan berikut: menjarah energi asal bidang target, menyebarkan ideologi bidang sendiri secara paksa, melakukan modifikasi genetik atau kesadaran tanpa persetujuan, mendirikan pangkalan militer permanen di bidang target, dan segala bentuk dominasi kolonial.</p><h2 id="_3-persyaratan-teknologi-dan-ambang-energi-penyeberangan" tabindex="-1">3. Persyaratan Teknologi dan Ambang Energi Penyeberangan <a class="header-anchor" href="#_3-persyaratan-teknologi-dan-ambang-energi-penyeberangan" aria-label="Permalink to &quot;3. Persyaratan Teknologi dan Ambang Energi Penyeberangan&quot;">​</a></h2><p>Penyeberangan bidang memerlukan pemenuhan kondisi teknologi yang ketat. Pertama, penyeberang harus memiliki kultivasi tahap ketiga (Kekosongan Transformasi) atau lebih tinggi dari &quot;sistem pengaturan hukum ruang&quot;, atau mengangkut kendaraan penyeberangan bidang yang memenuhi standar. Kedua, baik titik awal maupun titik akhir penyeberangan harus memiliki neo untuk kalibrasi koordinat; penyeberangan buta tanpa pemosisian neo dilarang keras.</p><p>Konsumsi energi selama proses penyeberangan berbanding lurus dengan intensitas hambatan hukum bidang target. Hengyuanzhou telah menetapkan &quot;tabel ambang energi penyeberangan&quot; yang standar, dan energi minimum yang diperlukan untuk penyeberangan berbagai jenis bidang adalah sebagai berikut:</p><ul><li>Bidang dasar material: 1000 unit energi standar</li><li>Bidang manifestasi energi: 5000 unit energi standar</li><li>Bidang dominan kesadaran: 20000 unit energi standar</li><li>Bidang hukum rusak: 50000 unit energi standar (dan tingkat keberhasilan di bawah 30%)</li><li>Bidang dekat asal: nilai teoretis di atas 100000, saat ini tidak ada catatan keberhasilan</li></ul><p>Energi penyeberangan harus dibawa oleh penyeberang atau kendaraan itu sendiri, dilarang mengekstrak energi dari bidang target untuk proses penyeberangan. Ketentuan ini bertujuan untuk mencegah tindakan penyeberangan menyebabkan penjarahan energi pada bidang target.</p><h2 id="_4-pencegahan-dan-pengendalian-polusi-dalam-proses-penyeberangan" tabindex="-1">4. Pencegahan dan Pengendalian Polusi dalam Proses Penyeberangan <a class="header-anchor" href="#_4-pencegahan-dan-pengendalian-polusi-dalam-proses-penyeberangan" aria-label="Permalink to &quot;4. Pencegahan dan Pengendalian Polusi dalam Proses Penyeberangan&quot;">​</a></h2><p>Salah satu risiko terbesar penyeberangan bidang adalah &quot;polusi antar bidang&quot;, yang meliputi polusi biologis (membawa mikroorganisme dari bidang sendiri ke bidang target), polusi energi (gangguan sisa energi bidang sendiri terhadap hukum bidang target), dan polusi kesadaran (fluktuasi kesadaran penyeberang memengaruhi domain kesadaran bidang target).</p><p>Untuk mencegah dan mengendalikan polusi, semua penyeberang harus menyelesaikan &quot;program pemurnian tiga tingkat&quot; sebelum keberangkatan:</p><ol><li><strong>Pemurnian biologis</strong>: Melakukan penyaringan dan eliminasi mikroba selama 72 jam di ruang terisolasi, memastikan tidak membawa patogen apa pun dari bidang sendiri</li><li><strong>Pemurnian energi</strong>: Menyesuaikan frekuensi energi penyeberang ke rentang yang kompatibel dengan bidang target melalui perangkat kalibrasi neo, mengurangi reaksi penolakan energi</li><li><strong>Pemurnian kesadaran</strong>: Melakukan pelatihan pemblokiran kesadaran, memastikan selama proses penyeberangan tidak melepaskan secara aktif fluktuasi kehendak yang dapat mengganggu domain kesadaran bidang target</li></ol><p>Selain itu, ruang lingkup kegiatan penyeberang di bidang target dibatasi secara ketat dalam &quot;wilayah yang ditetapkan oleh izin penyeberangan&quot;, penyebaran tanpa otorisasi dilarang. Setelah kembali ke bidang sendiri, penyeberang harus kembali menjalani observasi terisolasi untuk waktu tidak kurang dari 30 hari yang dikonversi berdasarkan kecepatan aliran waktu bidang target.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Aturan penyeberangan bidang adalah garis pertahanan keamanan pertama dari interaksi antar bidang. Melalui tiga mekanisme — klasifikasi izin, ambang batas teknologi, dan pencegahan polusi — memastikan bahwa tindakan penyeberangan selalu beroperasi di jalur &quot;dampak rendah, dapat dilacak, dapat dipertanggungjawabkan&quot;. Tujuan akhir aturan bukanlah membatasi pertukaran antar peradaban, melainkan membuat pertukaran terjadi dengan cara simbiosis, bukan dengan cara penjarahan.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>80-Teori dan Klasifikasi Bidang</li><li>88-Pedoman Etika Antar Bidang</li><li>62-Implementasi Teknologi Hukum Ruang</li></ul>',23)])])}const o=n(r,[["render",d]]);export{b as __pageData,o as default};
